// Inserts 20 million KV pairs into a trie. Measures the overhead of
// incrementally adding an additional 2 million KV pairs. No hashing occurs
// after each insert. Rather, hashing is performanced once for all nodes at the
// end.
void
insert_when_already_large_hash_once_at_end(benchmark::State &state)
{
  MerkleTrie trie;
  trie.set_should_hash_nodes_on_each_op(false);

  std::vector<HexArray> paths =
      precompute_paths(/*num_paths=*/kLargeNumKVPairs);
  for (const auto &path : paths) {
    CHECK(trie.insert(path, "hello"));
  }
  trie.generate_all_hashes();

  paths = precompute_paths(/*num_paths=*/kNumKVPairs);
  for (auto _ : state) {
    for (const auto &path : paths) {
      CHECK(trie.insert(path, "hello"));
    }
    trie.generate_all_hashes();
  }
}
BENCHMARK(insert_when_already_large_hash_once_at_end)
    ->Iterations(1)
    ->Unit(benchmark::kSecond);

// Removes 2 million KV pairs from a trie. Nodes are hashed after each
// [remove()] operation.
void
remove_two_million(benchmark::State &state)
{
  MerkleTrie trie;

  std::vector<HexArray> paths = precompute_paths(/*num_paths=*/kNumKVPairs);
  for (const auto &path : paths) {
    CHECK(trie.insert(path, "hello"));
  }
  for (auto _ : state) {
    for (const auto &path : paths) {
      trie.remove(path);
    }
  }
}
BENCHMARK(remove_two_million)->Iterations(1)->Unit(benchmark::kSecond);

// Removes 2 million KV pairs from a trie. Nodes are *not* hashed at any point.
void
remove_two_million_no_hash(benchmark::State &state)
{
  MerkleTrie trie;
  trie.set_should_hash_nodes_on_each_op(false);

  std::vector<HexArray> paths = precompute_paths(/*num_paths=*/kNumKVPairs);
  for (const auto &path : paths) {
    CHECK(trie.insert(path, "hello"));
  }
  for (auto _ : state) {
    for (const auto &path : paths) {
      trie.remove(path);
    }
  }
}
BENCHMARK(remove_two_million_no_hash)->Iterations(1)->Unit(benchmark::kSecond);

// Removes 2 million KV pairs from a trie. Nodes are *not* hashed after each
// [remove()] operation. We just rehash at the end (though the rehash is quick
// since only the root node remains).
void
remove_two_million_hash_once_at_end(benchmark::State &state)
{
  MerkleTrie trie;
  trie.set_should_hash_nodes_on_each_op(false);

  std::vector<HexArray> paths = precompute_paths(/*num_paths=*/kNumKVPairs);
  for (const auto &path : paths) {
    CHECK(trie.insert(path, "hello"));
  }
  for (auto _ : state) {
    for (const auto &path : paths) {
      trie.remove(path);
    }
    trie.generate_all_hashes();
  }
}
BENCHMARK(remove_two_million_hash_once_at_end)
    ->Iterations(1)
    ->Unit(benchmark::kSecond);

// Finds a single KV pair.
void
find(benchmark::State &state)
{
  MerkleTrie trie;
  trie.set_should_hash_nodes_on_each_op(false);

  std::vector<HexArray> paths = precompute_paths(/*num_paths=*/kNumKVPairs);
  for (const auto &path : paths) {
    CHECK(trie.insert(path, "hello"));
  }
  trie.generate_all_hashes();
  trie.set_should_hash_nodes_on_each_op(true);

  for (auto _ : state) {
    CHECK_PTR(trie.find(paths[0]));
  }
}
BENCHMARK(find)->Unit(benchmark::kNanosecond);

// Generates a proof for a single KV pair.
void
get_proof(benchmark::State &state)
{
  MerkleTrie trie;
  trie.set_should_hash_nodes_on_each_op(false);

  std::vector<HexArray> paths = precompute_paths(/*num_paths=*/kNumKVPairs);
  for (const auto &path : paths) {
    CHECK(trie.insert(path, "hello"));
  }
  trie.generate_all_hashes();
  trie.set_should_hash_nodes_on_each_op(true);

  for (auto _ : state) {
    const auto &pair = trie.get_proof(paths[0]);
    (void)pair;
  }
}
BENCHMARK(get_proof)->Unit(benchmark::kMicrosecond);

// Checks the proof for a single KV pair.
void
prove(benchmark::State &state)
{
  MerkleTrie trie;
  trie.set_should_hash_nodes_on_each_op(false);

  std::vector<HexArray> paths = precompute_paths(/*num_paths=*/kNumKVPairs);
  for (const auto &path : paths) {
    CHECK(trie.insert(path, "hello"));
  }
  trie.generate_all_hashes();
  trie.set_should_hash_nodes_on_each_op(true);

  const auto &pair = trie.get_proof(paths[0]);
  for (auto _ : state) {
    CHECK(trie.prove(pair.first, pair.second, paths[0], "hello"));
  }
}
BENCHMARK(prove)->Unit(benchmark::kMicrosecond);

void
hash_parallel(benchmark::State &state, int num_threads)
{
  constexpr size_t kTotalHashes = 20'000'000;
  const size_t per_thread_iterations = kTotalHashes / num_threads;

  std::vector<std::byte> init(100);
  std::vector<std::vector<std::byte>> to_hash(num_threads, init);

  WorkerPool pool(num_threads);
  std::vector<std::future<void>> futures(num_threads);

  for (auto _ : state) {
    for (size_t i = 0; i < num_threads; i++) {
      futures[i] = pool.submit([per_thread_iterations, i, &to_hash] {
        for (size_t j = 0; j < per_thread_iterations; j++) {
          sha256(to_hash[i]);
          to_hash[i][0] = std::byte(static_cast<uint8_t>(to_hash[i][0]) + 1);
        }
      });
    }
    for (std::future<void> &future : futures) {
      future.get();
    }
  }
}

void hash_parallel_1_thread(benchmark::State &state) {
  hash_parallel(state, /*num_threads=*/1);
}
BENCHMARK(hash_parallel_1_thread)->Unit(benchmark::kMillisecond);

void hash_parallel_64_threads(benchmark::State &state) {
  hash_parallel(state, /*num_threads=*/64);
}
BENCHMARK(hash_parallel_64_threads)->Unit(benchmark::kMillisecond);

void hash_parallel_128_threads(benchmark::State &state) {
  hash_parallel(state, /*num_threads=*/128);
}
BENCHMARK(hash_parallel_128_threads)->Unit(benchmark::kMillisecond);

